select fixture_assert((select not prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='public.save_household_nickname(uuid,text,text)'::regprocedure),'invoker endpoint and empty search path');
select fixture_assert((select relrowsecurity from pg_class where oid='public.household_nicknames'::regclass),'nickname RLS enabled');
select fixture_assert(not has_table_privilege('anon','public.household_nicknames','SELECT') and not has_table_privilege('anon','public.household_nicknames','INSERT') and not has_function_privilege('anon','public.save_household_nickname(uuid,text,text)','EXECUTE'),'anon denied table and endpoint');
select fixture_assert(not has_table_privilege('authenticated','public.household_nicknames','TRUNCATE'),'authenticated has no TRUNCATE');
select fixture_assert((select confdeltype='c' and array_length(conkey,1)=2 from pg_constraint where conname='household_nicknames_current_member_fkey'),'current membership composite FK cascades');
select fixture_assert(exists(select 1 from pg_indexes where tablename='household_nicknames' and indexname='household_nicknames_member_idx'),'membership cascade indexed');
set role authenticated;
select set_config('request.jwt.claim.sub','',false);
select fixture_error($q$select save_household_nickname('00000000-0000-4000-8000-000000000002','A',null)$q$,'Sign in');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000099',false);
select fixture_error($q$select save_household_nickname('00000000-0000-4000-8000-000000000002','A',null)$q$,'membership required');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000011',false);
select fixture_assert(save_household_nickname('00000000-0000-4000-8000-000000000002',' Owner   home ',null)->>'nickname'='Owner home','owner self nickname normalized');
select fixture_assert(save_household_nickname('00000000-0000-4000-8000-000000000001','Personal 🏡',null)->>'nickname'='Personal 🏡','personal household self nickname');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000012',false);
select fixture_assert(save_household_nickname('00000000-0000-4000-8000-000000000002','Manager home',null)->>'user_id'='00000000-0000-4000-8000-000000000012','manager self nickname');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000013',false);
select fixture_assert(save_household_nickname('00000000-0000-4000-8000-000000000002','Cousin''s home & 🏡',null)->>'nickname'='Cousin''s home & 🏡','editor self nickname');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000014',false);
select fixture_assert(save_household_nickname('00000000-0000-4000-8000-000000000002','Viewer home',null)->>'nickname'='Viewer home','viewer self nickname without member UPDATE grant');
select fixture_assert((select count(*)=1 from public.household_nicknames),'viewer sees only own nickname');
select fixture_error($q$insert into public.household_nicknames(user_id,household_id,nickname)values('00000000-0000-4000-8000-000000000013','00000000-0000-4000-8000-000000000002','Forged')$q$,'row-level security');
select fixture_error($q$update public.household_nicknames set user_id='00000000-0000-4000-8000-000000000013' where user_id='00000000-0000-4000-8000-000000000014'$q$,'row-level security');
select fixture_error($q$update public.household_nicknames set household_id='00000000-0000-4000-8000-000000000003'$q$,'row-level security');
select fixture_error($q$select save_household_nickname('00000000-0000-4000-8000-000000000002','Other','Stale')$q$,'household_nickname_conflict');
select fixture_assert(save_household_nickname('00000000-0000-4000-8000-000000000002','Viewer home','Stale')->>'nickname'='Viewer home','desired state retry idempotent');
select fixture_assert(save_household_nickname('00000000-0000-4000-8000-000000000002',null,'Viewer home')->'nickname'='null'::jsonb,'explicit remove returns canonical null');
select fixture_assert(save_household_nickname('00000000-0000-4000-8000-000000000002',null,'Viewer home')->'nickname'='null'::jsonb,'lost remove ACK safely retryable');
select fixture_assert((select count(*)=0 from public.household_nicknames),'removed nickname is absent');
insert into public.household_nicknames(user_id,household_id,nickname) values('00000000-0000-4000-8000-000000000014','00000000-0000-4000-8000-000000000002','Direct REST');
select fixture_assert((select nickname='Direct REST' from public.household_nicknames),'direct REST-shaped own INSERT allowed');
update public.household_nicknames set nickname='Direct edit';
select fixture_assert((select nickname='Direct edit' from public.household_nicknames),'direct REST-shaped own UPDATE allowed');
delete from public.household_nicknames;
select fixture_assert((select count(*)=0 from public.household_nicknames),'direct REST-shaped own DELETE allowed');
select fixture_error($q$insert into public.household_nicknames values('00000000-0000-4000-8000-000000000014','00000000-0000-4000-8000-000000000002','',now())$q$,'check constraint');
select fixture_error($q$insert into public.household_nicknames values('00000000-0000-4000-8000-000000000014','00000000-0000-4000-8000-000000000002','  ',now())$q$,'check constraint');
select fixture_error($q$insert into public.household_nicknames values('00000000-0000-4000-8000-000000000014','00000000-0000-4000-8000-000000000002',repeat('x',81),now())$q$,'check constraint');
select fixture_error($q$insert into public.household_nicknames values('00000000-0000-4000-8000-000000000014','00000000-0000-4000-8000-000000000002','a'||chr(1),now())$q$,'check constraint');
select fixture_error($q$select save_household_nickname('00000000-0000-4000-8000-000000000002',' ',null)$q$,'1 to 80');
select fixture_error($q$select save_household_nickname('00000000-0000-4000-8000-000000000002',repeat('🏡',81),null)$q$,'1 to 80');
select fixture_assert(save_household_nickname('00000000-0000-4000-8000-000000000002',repeat('🏡',80),null)->>'nickname'=repeat('🏡',80),'80 Unicode points accepted');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000011',false);
select fixture_assert((select count(*)=2 from public.household_nicknames),'owner cannot read other same-household members nicknames');
do $$declare changed integer;begin update public.household_nicknames set nickname='Invade' where user_id='00000000-0000-4000-8000-000000000014';get diagnostics changed=row_count;perform fixture_assert(changed=0,'owner cannot update another member nickname');delete from public.household_nicknames where user_id='00000000-0000-4000-8000-000000000014';get diagnostics changed=row_count;perform fixture_assert(changed=0,'owner cannot delete another member nickname');end$$;
reset role;
select fixture_assert((select jsonb_agg(to_jsonb(h)order by id)from public.households h)=(select households from nickname_fixture_before),'shared names and household metadata unchanged');
select fixture_assert((select jsonb_agg(to_jsonb(m)order by household_id,user_id)from public.household_members m)=(select members from nickname_fixture_before),'memberships unchanged');
select fixture_assert((select jsonb_agg(to_jsonb(f))from public.financial_fixture f)=(select finances from nickname_fixture_before),'financial data unchanged');
delete from public.household_members where user_id='00000000-0000-4000-8000-000000000014';
select fixture_assert(not exists(select 1 from public.household_nicknames where user_id='00000000-0000-4000-8000-000000000014'),'membership deletion cascades nickname');
select 'HOUSEHOLD NICKNAME TESTS COMPLETE';
